-- Shared helpers for snes/test/audio/*.lua (prepended by run.mjs).
-- The prelude defines UPLOAD (path of dist/snes/gen/audio/upload.bin) and
-- the cue ids (AUDIO_*) generated by snes/gen/audio.mjs.
AU = 0x7EDD00
AU_TEST = AU + 0x16
local failures = 0
function check(name, ok, detail)
  if ok then H.result(name, 'pass') else
    failures = failures + 1
    H.result(name, 'FAIL ' .. tostring(detail or ''))
  end
  return ok
end
function finish() H.result('failures', failures) end
function aram(a) return emu.read(a, emu.memType.spcRam) end
function dsp(r) return emu.read(r, emu.memType.spcDspRegisters) end
function port3() return aram(0xE6) end   -- the status byte the SPC publishes on port 3
-- Mailbox op | arg<<8 (snes/src/modules/audio/module.asm audio_test_poll).
function cmd(op, arg) H.w8(AU_TEST + 1, arg or 0); H.w8(AU_TEST, op) end

-- Write the current extension (segments and driver patches from upload.bin)
-- into ARAM right after a state loads, before any frame runs: states saved by
-- other builds then run today's extension. The SPC is in driver code at any
-- instruction boundary (the extension regions are unused by the driver).
function injectExtension()
  local f = assert(io.open(UPLOAD, 'rb'))
  local data = f:read('*a')
  f:close()
  local i = 1
  while i + 3 <= #data do
    local addr = data:byte(i) | (data:byte(i + 1) << 8)
    local len = data:byte(i + 2) | (data:byte(i + 3) << 8)
    if len == 0 then return true end
    for k = 0, len - 1 do emu.write(addr + k, data:byte(i + 4 + k), emu.memType.spcRam) end
    i = i + 4 + len
  end
  return false
end

-- Per-frame DSP view of one voice: SRCN, ENVX, OUTX (signed).
function voiceState(v)
  local o = dsp(v * 16 + 9)
  if o >= 128 then o = o - 256 end
  return { srcn = dsp(v * 16 + 4), envx = dsp(v * 16 + 8), outx = o,
           voll = dsp(v * 16), pitch = dsp(v * 16 + 2) | (dsp(v * 16 + 3) << 8) }
end
function voicesEnv()
  local t = {}
  for v = 0, 7 do t[#t + 1] = dsp(v * 16 + 8) end
  return t
end
